"""Check the actual quadrature source refusal, separately from package admission."""
import argparse
import json
import subprocess
from pathlib import Path
import sys
# Keep generated bytecode outside the accepted source identity.
sys.dont_write_bytecode = True
from check_output import ROOT, frozen
parser = argparse.ArgumentParser()
parser.add_argument('--omega', required=True)
arguments = parser.parse_args()
frozen()
command = [arguments.omega, '--check', str(ROOT/'model/intended_invalid.omg')]
result = subprocess.run(command, stdin=subprocess.DEVNULL, capture_output=True, timeout=90)
output = result.stdout + result.stderr
assert result.returncode == 1, (result.returncode, output)
for fragment in (ROOT/'controls/intended_invalid/expected.txt').read_text().splitlines():
    assert fragment.encode() in output, (fragment, output)
assert b'accepted program-entry' not in output
assert b'failed to resolve' not in output
assert b'cannot open private source resolver' not in output
destination = ROOT/'build/validation/source-invalid'
destination.mkdir(parents=True, exist_ok=True)
(destination/'stdout.txt').write_bytes(result.stdout)
(destination/'stderr.txt').write_bytes(result.stderr)
(destination/'verified.json').write_text(json.dumps(dict(command=command, exit=result.returncode),indent=2)+'\n')
print('verified actual quadrature source-bound refusal')
